using System;using System.Drawing;using System.Windows.Forms;using System.Collections.Generic;using System.Linq;
namespace Citograph.Word {
 internal class ReferencePicker:Form {
  private LibraryResponse library;private List<Dictionary<string,object>> travel;private ListView list;private TextBox search;private ComboBox source;private Label count,detail;private TextBox locator,prefix,suffix;private CheckBox suppress;private Button action;
  private List<Dictionary<string,object>> all;private HashSet<string> selected=new HashSet<string>();
  public List<Dictionary<string,object>> SelectedReferences {get{return all.Where(r=>selected.Contains(Data.Text(r,"id"))).ToList();}}
  public string Locator {get{return locator.Text.Trim();}}public string Prefix {get{return prefix.Text;}}public string Suffix {get{return suffix.Text;}}public bool SuppressAuthor {get{return suppress.Checked;}}
  private class SourceChoice {public string id,name;public override string ToString(){return name;}}
  public ReferencePicker(LibraryResponse data,List<Dictionary<string,object>> traveling,string title,CitationPayload editing=null){
   library=data;travel=traveling;all=Data.Unique(data.references.Concat(traveling));if(editing!=null)foreach(var item in editing.items)selected.Add(item.id);
   Text="Citograph · "+title;Size=new Size(990,710);MinimumSize=new Size(850,630);StartPosition=FormStartPosition.CenterParent;Font=new Font("Segoe UI",9.5f);BackColor=Color.FromArgb(247,248,251);ShowIcon=true;try{Icon=new Icon(System.Reflection.Assembly.GetExecutingAssembly().GetManifestResourceStream("Citograph.Icon.ico"));}catch{}
   var shell=new TableLayoutPanel{Dock=DockStyle.Fill,RowCount=5,ColumnCount=1,Padding=new Padding(0)};shell.RowStyles.Add(new RowStyle(SizeType.Absolute,94));shell.RowStyles.Add(new RowStyle(SizeType.Absolute,64));shell.RowStyles.Add(new RowStyle(SizeType.Percent,100));shell.RowStyles.Add(new RowStyle(SizeType.Absolute,129));shell.RowStyles.Add(new RowStyle(SizeType.Absolute,64));Controls.Add(shell);
   var header=new Panel{Width=942,Dock=DockStyle.Fill,BackColor=Color.FromArgb(33,35,50)};header.Controls.Add(new Label{Text="CITOGRAPH  /  WORD",ForeColor=Color.FromArgb(160,142,208),Font=new Font("Segoe UI",8,FontStyle.Bold),Location=new Point(24,15),AutoSize=true});header.Controls.Add(new Label{Text=title,ForeColor=Color.White,Font=new Font("Segoe UI Semibold",21),Location=new Point(23,35),AutoSize=true});header.Controls.Add(new Label{Text="YOUR SOURCES, RIGHT WHERE YOU WRITE.",ForeColor=Color.FromArgb(123,125,148),Font=new Font("Segoe UI",8),Anchor=AnchorStyles.Top|AnchorStyles.Right,TextAlign=ContentAlignment.MiddleRight,Location=new Point(555,45),Size=new Size(385,20)});shell.Controls.Add(header,0,0);
   var filters=new TableLayoutPanel{Dock=DockStyle.Fill,ColumnCount=2,Padding=new Padding(24,15,24,10)};filters.ColumnStyles.Add(new ColumnStyle(SizeType.Percent,100));filters.ColumnStyles.Add(new ColumnStyle(SizeType.Absolute,245));search=new TextBox{Dock=DockStyle.Fill,Font=new Font("Segoe UI",11),Margin=new Padding(0,2,14,0)};source=new ComboBox{Dock=DockStyle.Fill,DropDownStyle=ComboBoxStyle.DropDownList,Font=new Font("Segoe UI",10),Margin=new Padding(0,1,0,0)};source.Items.Add(new SourceChoice{id="all",name="All sources"});source.Items.Add(new SourceChoice{id="travel",name="This document · traveling library"});foreach(var c in data.collections)source.Items.Add(new SourceChoice{id=c.id,name=c.name});source.SelectedIndex=title.Contains("Traveling")?1:0;filters.Controls.Add(search,0,0);filters.Controls.Add(source,1,0);shell.Controls.Add(filters,0,1);
   var workspace=new SplitContainer{Dock=DockStyle.Fill,Width=940,SplitterDistance=650,Panel1MinSize=470,Panel2MinSize=230,FixedPanel=FixedPanel.Panel2,Padding=new Padding(24,0,24,0),BackColor=Color.FromArgb(247,248,251),SplitterWidth=12};list=new ListView{Dock=DockStyle.Fill,View=View.Details,FullRowSelect=true,CheckBoxes=true,HideSelection=false,BorderStyle=BorderStyle.FixedSingle,BackColor=Color.White,ForeColor=Color.FromArgb(53,58,76),MultiSelect=false};list.Columns.Add("REFERENCE",430);list.Columns.Add("YEAR",55);list.Columns.Add("TYPE",90);workspace.Panel1.Padding=new Padding(24,0,0,0);workspace.Panel2.Padding=new Padding(0,0,24,0);workspace.Panel1.Controls.Add(list);var detailPanel=new Panel{Dock=DockStyle.Fill,BackColor=Color.White,Padding=new Padding(15)};detail=new Label{Dock=DockStyle.Fill,ForeColor=Color.FromArgb(132,133,153),Font=new Font("Segoe UI",9),Text="A closer look\r\n\r\nSelect a source to see its metadata.\r\n\r\nCheck one or more sources to build a grouped citation.",AutoSize=false};detailPanel.Controls.Add(detail);workspace.Panel2.Controls.Add(detailPanel);shell.Controls.Add(workspace,0,2);
   var options=new TableLayoutPanel{Dock=DockStyle.Fill,ColumnCount=3,RowCount=3,Padding=new Padding(24,15,24,7)};options.ColumnStyles.Add(new ColumnStyle(SizeType.Percent,24));options.ColumnStyles.Add(new ColumnStyle(SizeType.Percent,38));options.ColumnStyles.Add(new ColumnStyle(SizeType.Percent,38));options.RowStyles.Add(new RowStyle(SizeType.Absolute,23));options.RowStyles.Add(new RowStyle(SizeType.Absolute,31));options.RowStyles.Add(new RowStyle(SizeType.Absolute,31));string[] labels={"PAGE LOCATOR","PREFIX · e.g. see ","SUFFIX · e.g. for details"};for(int i=0;i<3;i++)options.Controls.Add(new Label{Text=labels[i],ForeColor=Color.FromArgb(137,132,158),Font=new Font("Segoe UI",8),AutoSize=true,Margin=new Padding(0,0,0,3)},i,0);locator=new TextBox{Dock=DockStyle.Fill,Margin=new Padding(0,0,12,0)};prefix=new TextBox{Dock=DockStyle.Fill,Margin=new Padding(0,0,12,0)};suffix=new TextBox{Dock=DockStyle.Fill,Margin=new Padding(0)};suppress=new CheckBox{Text="Suppress author name (author–date styles)",AutoSize=true,ForeColor=Color.FromArgb(143,133,161),Margin=new Padding(0,9,0,0)};options.Controls.Add(locator,0,1);options.Controls.Add(prefix,1,1);options.Controls.Add(suffix,2,1);options.Controls.Add(suppress,0,2);options.SetColumnSpan(suppress,3);if(editing!=null&&editing.items.Count>0){locator.Text=editing.items[0].locator;prefix.Text=editing.items[0].prefix;suffix.Text=editing.items.Last().suffix;suppress.Checked=editing.items[0].suppressAuthor;}shell.Controls.Add(options,0,3);
   var footer=new Panel{Width=942,Dock=DockStyle.Fill,BackColor=Color.White};count=new Label{AutoSize=true,Location=new Point(25,21),ForeColor=Color.FromArgb(143,133,161)};action=UI.Button(editing==null?"Insert selected sources":"Update citation",true);action.Size=new Size(183,36);action.Anchor=AnchorStyles.Top|AnchorStyles.Right;action.Location=new Point(758,12);action.Click+=(s,e)=>{if(selected.Count>0){DialogResult=DialogResult.OK;Close();}};var cancel=UI.Button("Cancel",false);cancel.Size=new Size(90,36);cancel.Anchor=AnchorStyles.Top|AnchorStyles.Right;cancel.Location=new Point(655,12);cancel.Click+=(s,e)=>{DialogResult=DialogResult.Cancel;Close();};footer.Controls.Add(count);footer.Controls.Add(action);footer.Controls.Add(cancel);shell.Controls.Add(footer,0,4);CancelButton=cancel;AcceptButton=action;
   search.HandleCreated+=(s,e)=>UI.Cue(search,"Search by title, author, DOI or journal…");search.TextChanged+=(s,e)=>Render();source.SelectedIndexChanged+=(s,e)=>Render();list.ItemChecked+=(s,e)=>{string id=(string)e.Item.Tag;if(e.Item.Checked)selected.Add(id);else selected.Remove(id);UpdateCount();};list.SelectedIndexChanged+=(s,e)=>{if(list.SelectedItems.Count==0)return;var r=all.First(x=>Data.Text(x,"id")==Convert.ToString(list.SelectedItems[0].Tag));detail.Text="SOURCE DETAILS\r\n\r\n"+Data.Text(r,"title")+"\r\n\r\n"+Data.Authors(r)+"\r\n\r\n"+Data.Year(r)+" · "+Data.Text(r,"container-title")+"\r\n\r\nDOI\r\n"+Data.Text(r,"DOI")+"\r\n\r\n"+(Data.Text(r,"abstract").Length>600?Data.Text(r,"abstract").Substring(0,600)+"…":Data.Text(r,"abstract"));};Shown+=(s,e)=>search.Focus();Render();
  }
  private void UpdateCount(){count.Text=selected.Count+" selected · "+all.Count+" available sources";action.Enabled=selected.Count>0;}
  private void Render(){var saved=new HashSet<string>(selected);list.BeginUpdate();list.Items.Clear();string query=search.Text.Trim().ToLowerInvariant();string sourceId=((SourceChoice)source.SelectedItem).id;foreach(var r in all){string id=Data.Text(r,"id");if(sourceId=="travel"&&!Data.HasId(travel,id))continue;if(sourceId!="all"&&sourceId!="travel"){object cs;if(!r.TryGetValue("collections",out cs)||!Data.Serialize(cs).Contains("\""+sourceId+"\""))continue;}if(!(Data.Text(r,"title")+" "+Data.Authors(r)+" "+Data.Text(r,"DOI")+" "+Data.Text(r,"container-title")).ToLowerInvariant().Contains(query))continue;var item=new ListViewItem(Data.Text(r,"title")){Tag=id,ToolTipText=Data.Authors(r),Checked=saved.Contains(id)};item.SubItems.Add(Data.Year(r));item.SubItems.Add(Data.Text(r,"type").Replace("article-journal","Journal"));list.Items.Add(item);}list.EndUpdate();selected=saved;UpdateCount();}
 }
 internal static class UI {
  [System.Runtime.InteropServices.DllImport("user32.dll",CharSet=System.Runtime.InteropServices.CharSet.Unicode)]private static extern IntPtr SendMessage(IntPtr handle,int message,IntPtr parameter,string text);
  public static void Cue(TextBox box,string text){SendMessage(box.Handle,0x1501,IntPtr.Zero,text);}
  public static Button Button(string text,bool primary){var button=new Button{Text=text,FlatStyle=FlatStyle.Flat,Font=new Font("Segoe UI Semibold",9.5f),BackColor=primary?Color.FromArgb(117,97,217):Color.White,ForeColor=primary?Color.White:Color.FromArgb(127,119,145),Cursor=Cursors.Hand,UseVisualStyleBackColor=false};button.FlatAppearance.BorderSize=primary?0:1;button.FlatAppearance.BorderColor=Color.FromArgb(230,225,237);return button;}
  public static Form Report(string title,string summary,string details){var form=new Form{Text="Citograph · "+title,Size=new Size(700,600),StartPosition=FormStartPosition.CenterParent,BackColor=Color.FromArgb(247,248,251),Font=new Font("Segoe UI",10)};var header=new Label{Dock=DockStyle.Top,Height=99,Padding=new Padding(25,20,25,10),Text=title+"\r\n"+summary,BackColor=Color.FromArgb(33,35,50),ForeColor=Color.White,Font=new Font("Segoe UI",13)};var box=new TextBox{Dock=DockStyle.Fill,Multiline=true,ReadOnly=true,ScrollBars=ScrollBars.Vertical,BorderStyle=BorderStyle.None,BackColor=Color.White,ForeColor=Color.FromArgb(118,113,138),Text=details,Font=new Font("Segoe UI",10)};var body=new Panel{Dock=DockStyle.Fill,Padding=new Padding(25)};body.Controls.Add(box);var footer=new Panel{Width=684,Dock=DockStyle.Bottom,Height=68};var close=Button("Done",true);close.Size=new Size(100,35);close.Location=new Point(560,15);close.Anchor=AnchorStyles.Top|AnchorStyles.Right;close.Click+=(s,e)=>form.Close();footer.Controls.Add(close);form.Controls.Add(body);form.Controls.Add(footer);form.Controls.Add(header);return form;}
 }
